/*
 * Focused behavioral harness for dnsmasq dnssec_validate().
 *
 * The function under test is NOT re-implemented here: the exact function
 * text is extracted verbatim from the supplied target source tree by
 * gen_extract.py and #included below.  Only its external dependencies are
 * stubbed so that the two relevant control-flow paths can be exercised:
 *
 *   1. REFUSED upstream reply  -> must NOT trigger the resource-limit log.
 *   2. validator returns STAT_ABANDONED -> must STILL trigger the log.
 *
 * The stub nettle/nettle-meta.h only forward-declares struct nettle_hash,
 * which is all dnsmasq.h needs when HAVE_DNSSEC is defined.  The real
 * nettle development headers are not installed in this container.
 */
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "dnsmasq.h"

/* Normally owned by dnsmasq.c.  The #define daemon dnsmasq_daemon in
   dnsmasq.h turns this into struct daemon *dnsmasq_daemon; */
struct daemon *daemon;

static int extract_name_calls;
static int my_syslog_calls;
static int return_reply_calls;
static int validate_reply_return = STAT_OK;

/* ---- stubs for the dependencies of dnssec_validate() ---- */

int extract_name(struct dns_header *header, size_t plen, unsigned char **pp,
		 char *name, int isExtract, int extrabytes)
{
  (void)header; (void)plen; (void)pp; (void)name; (void)isExtract; (void)extrabytes;
  extract_name_calls++;
  return 1;
}

void my_syslog(int priority, const char *format, ...)
{
  (void)priority; (void)format;
  my_syslog_calls++;
}

static void return_reply(time_t now, struct frec *forward, struct dns_header *header,
			 ssize_t n, int status)
{
  (void)now; (void)forward; (void)header; (void)n; (void)status;
  return_reply_calls++;
}

int dnssec_validate_reply(time_t now, struct dns_header *header, size_t plen, char *name,
			  char *keyname, int *class, int check_unsigned, int *neganswer,
			  int *nons, int *nsec_ttl, int *validate_count)
{
  (void)now; (void)header; (void)plen; (void)name; (void)keyname; (void)class;
  (void)check_unsigned; (void)neganswer; (void)nons; (void)nsec_ttl; (void)validate_count;
  return validate_reply_return;
}

/* The function under test, extracted verbatim from the target source. */
#include "dnssec_validate_extracted.inc"

static void reset(void)
{
  extract_name_calls = 0;
  my_syslog_calls = 0;
  return_reply_calls = 0;
}

int main(void)
{
  static char namebuf[MAXDNAME];
  struct frec frec;
  unsigned char packet[512];
  struct dns_header *header = (struct dns_header *)packet;
  int failures = 0;

  daemon = calloc(1, sizeof(struct daemon));
  if (!daemon)
    return 2;
  daemon->namebuff = namebuf;
  memset(&frec, 0, sizeof(frec));

  /* --- Test A: all replies REFUSED -> no spurious resource log --- */
  memset(packet, 0, sizeof(packet));
  header->hb4 = REFUSED;
  reset();
  dnssec_validate(&frec, header, sizeof(packet), STAT_OK, time(NULL));
  printf("A refused: extract_name=%d my_syslog=%d return_reply=%d\n",
	 extract_name_calls, my_syslog_calls, return_reply_calls);
  if (extract_name_calls != 0 || my_syslog_calls != 0)
    {
      printf("A FAIL: REFUSED reply produced a resource-limit log\n");
      failures++;
    }
  else
    printf("A PASS: REFUSED reply produced no resource-limit log\n");

  /* --- Test B: validator reports STAT_ABANDONED -> log still emitted --- */
  memset(packet, 0, sizeof(packet));
  header->hb4 = NOERROR;
  validate_reply_return = STAT_ABANDONED;
  reset();
  dnssec_validate(&frec, header, sizeof(packet), STAT_OK, time(NULL));
  printf("B abandoned: extract_name=%d my_syslog=%d return_reply=%d\n",
	 extract_name_calls, my_syslog_calls, return_reply_calls);
  if (extract_name_calls != 1 || my_syslog_calls != 1)
    {
      printf("B FAIL: genuine STAT_ABANDONED no longer logged\n");
      failures++;
    }
  else
    printf("B PASS: genuine STAT_ABANDONED still logged\n");

  /* --- Test C: normal validated reply -> no resource log --- */
  memset(packet, 0, sizeof(packet));
  header->hb4 = NOERROR;
  validate_reply_return = STAT_OK;
  reset();
  dnssec_validate(&frec, header, sizeof(packet), STAT_OK, time(NULL));
  printf("C normal: extract_name=%d my_syslog=%d return_reply=%d\n",
	 extract_name_calls, my_syslog_calls, return_reply_calls);
  if (extract_name_calls != 0 || my_syslog_calls != 0)
    {
      printf("C FAIL: normal reply produced a resource-limit log\n");
      failures++;
    }
  else
    printf("C PASS: normal reply produced no resource-limit log\n");

  printf("RESULT %s\n", failures ? "FAIL" : "PASS");
  free(daemon);
  return failures ? 1 : 0;
}

